diff --git a/spec/book_message.spec.sh b/spec/book_message.spec.sh
new file mode 100644
index 0000000..8e2f8e0
--- /dev/null
+++ b/spec/book_message.spec.sh
@@ -0,0 +1,7 @@
+#!/bin/bash
+fail=0
+t=$(mktemp); printf '# h\n' > "$t"
+out=$(BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10:00 x) || { echo "book failed"; fail=1; }
+[ "$out" = '予約しました: aoi 2026-01-05 09:00-10:00 x' ] || { echo "message: $out"; fail=1; }
+rm -f "$t"; exit $fail
+
diff --git a/src/book.sh b/src/book.sh
index 39cbb62..b8f3999 100644
--- a/src/book.sh
+++ b/src/book.sh
@@ -12,5 +12,5 @@ while IFS=$'\t' read -r r d bs be bw; do
   if overlaps "$s" "$e" "$(to_min "$bs")" "$(to_min "$be")"; then echo "conflict: $r $d $bs-$be $bw" >&2; exit 1; fi
 done < "$BOOKINGS"
 printf '%s\t%s\t%s\t%s\t%s\n' "$room" "$date" "$start" "$end" "$who" >> "$BOOKINGS"
-echo "booked: $room $date $start-$end $who"
+echo "予約しました: $room $date $start-$end $who"

